import{_ as e,o,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Tala","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/lumberjacking.md","filePath":"es/guide/professions/lumberjacking.md"}'),t={name:"es/guide/professions/lumberjacking.md"};function s(l,a,n,d,c,p){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="lumberjacking" tabindex="-1">Tala <a class="header-anchor" href="#lumberjacking" aria-label="Enlace permanente a &quot;Tala&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No establecido como jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Conoce los árboles que talas: especie, madurez, estado y madera aprovechable.</li><li>La selección y la tala controlada deben premiar el conocimiento frente a la tala indiscriminada.</li><li>Los árboles caídos podrían modificar rutas; las reglas de protección y recuperación siguen abiertas.</li></ul><p><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="progression-and-related-crafts"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actividad</th><th>Qué haces</th></tr></thead><tbody><tr><td>Evaluar</td><td>Evalúa la especie, la salud y la calidad aproximada de la madera antes de cortar.</td></tr><tr><td>Elegir un método</td><td>La tala rápida, la tala controlada y el corte selectivo son posibles <a href="/Syrolands-Public/es/guide/characters/techniques.html">técnicas</a>.</td></tr><tr><td>Conocer la región</td><td>Usa un diario forestal para ampliar el conocimiento de árboles y ecología local.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Dirección de Syrolands</th></tr></thead><tbody><tr><td>Cortar árboles proporciona troncos que pueden convertirse en tablas.</td><td>El estado del árbol y la selección deben mejorar el rendimiento útil, el tiempo y el desgaste de herramientas.</td></tr><tr><td>El ciclo de recolección conocido trata los árboles como fuentes de madera.</td><td>Un árbol talado podría ocupar espacio y modificar temporalmente un paso estrecho.</td></tr></tbody></table><p>La comparación usa los ciclos conocidos de los oficios de UO; las referencias oficiales también cubren expansiones posteriores. <a href="https://uo.com/wiki/ultima-online-wiki/skills/lumberjacking/" target="_blank" rel="noreferrer">Lumberjacking</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un leñador podría seleccionar madera sana para un fabricante de arcos y dejar los árboles de mala calidad. La tala controlada también podría obstruir una ruta donde lo permitan las protecciones del mundo.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progresión y compromisos <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Enlace permanente a &quot;Progresión y compromisos&quot;">​</a></h2><ul><li>Una mejor selección debe recuperar más madera útil con menos tiempo desperdiciado o desgaste de herramientas.</li><li>La regeneración, la sobreexplotación y los límites al bloqueo de rutas siguen sin decidirse. Los puentes improvisados son solo un posible uso posterior.</li></ul><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/professions/carpentry.html">Carpintería</a> · <a href="/Syrolands-Public/es/guide/professions/cooking.html">Cocina</a> · <a href="/Syrolands-Public/es/guide/world/living-world.html">Mundo vivo</a> · <a href="/Syrolands-Public/es/guide/professions/overview.html">Sistema de profesiones</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/professions/lumberjacking.html">Tala</a></p>',18)])])}const h=e(t,[["render",s]]);export{m as __pageData,h as default};
